static std::atomic<double> mlHero15btActualAbsY[4][2][ML_HERO_15BS_WAVELENGTH_BINS];
static std::atomic<double> mlHero15btReferenceAbsY[4][2][ML_HERO_15BS_WAVELENGTH_BINS];
